      scheduleRender()
    }
  } catch (err) {
    const detail =
      err && err.stack ? err.stack : err && err.message ? err.message : String(err)
    eagle.log.error(`[clipboard-watcher] poll error: ${detail}`)
    state.pollErrorCount += 1
    state.lastError = 'POLL_FAILED'
